        //2
        private String GetPagarePDF(FormatSettings formatSettings, ContractRequest request, String FingerprintImage, String FingerprintImage2 = null)
        {
            String pdfbase64 = Convert.ToBase64String(System.IO.File.ReadAllBytes(Path.Combine(_hostingEnvironment.WebRootPath, formatSettings.PathFileBase)));

            //if (!String.IsNullOrEmpty(FingerprintImage))
            //{
            //    pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, FingerprintImage, formatSettings.SignPage, formatSettings.SignFromX, formatSettings.SignFromY, formatSettings.SignWidth, formatSettings.SignHeight);
            //    //pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, BarCode, formatSettings.BarcodePage, formatSettings.BarcodeFromX, formatSettings.BarcodeFromY, formatSettings.BarcodeWidth, formatSettings.BarcodeHeight);

            //    if (!String.IsNullOrEmpty(FingerprintImage2))
            //        pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, FingerprintImage2, formatSettings.SignPage2, formatSettings.SignFromX2, formatSettings.SignFromY2, formatSettings.SignWidth, formatSettings.SignHeight);
            //    //pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, BarCode, formatSettings.BarcodePage2, formatSettings.BarcodeFromX2, formatSettings.BarcodeFromY2, formatSettings.BarcodeWidth, formatSettings.BarcodeHeight);

            //    //pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, FingerprintImage, formatSettings.SignPage3, formatSettings.SignFromX3, formatSettings.SignFromY3, formatSettings.SignWidth, formatSettings.SignHeight);
            //    ////pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, BarCode, formatSettings.BarcodePage3, formatSettings.BarcodeFromX3, formatSettings.BarcodeFromY3, formatSettings.BarcodeWidth, formatSettings.BarcodeHeight);

            //    //pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, FingerprintImage, formatSettings.SignPage4, formatSettings.SignFromX4, formatSettings.SignFromY4, formatSettings.SignWidth, formatSettings.SignHeight);
            //    ////pdfbase64 = PdfWorker.WriteImageInPdf(pdfbase64, BarCode, formatSettings.BarcodePage4, formatSettings.BarcodeFromX4, formatSettings.BarcodeFromY4, formatSettings.BarcodeWidth, formatSettings.BarcodeHeight);
            //}

            //Hoja 1
            pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $" {request.NroPagare}", 1, 9, iTextSharp.text.Element.ALIGN_LEFT, 105, 854, 0.0f);

            System.Globalization.CultureInfo cultureinfo = new System.Globalization.CultureInfo("es-PE");
            DateTime fechaTransaccion = DateTime.MinValue;
            bool formatTransaccion = DateTime.TryParse(request.FechaTransaccion, cultureinfo, System.Globalization.DateTimeStyles.None, out fechaTransaccion);
            if (formatTransaccion)
            {
                pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $" {request.LugarTransaccion + " " + fechaTransaccion.ToString("dd/MM/yy", new System.Globalization.CultureInfo("es-PE"))}", 1, 9, iTextSharp.text.Element.ALIGN_LEFT, 465, 892, 0.0f);

            }
            pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $" {request.ImportePagare}", 1, 9, iTextSharp.text.Element.ALIGN_LEFT, 430, 872, 0.0f);

            //System.Globalization.CultureInfo cultureinfo = new System.Globalization.CultureInfo("es-PE");
            DateTime fechaVencimiento = DateTime.MinValue;
            bool formatVencimiento = DateTime.TryParse(request.FechaVencimiento, cultureinfo, System.Globalization.DateTimeStyles.None, out fechaVencimiento);
            if (formatVencimiento)
            {
                pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $" {fechaVencimiento.ToString("dd")}", 1, 9, iTextSharp.text.Element.ALIGN_LEFT, 400, 853, 0.0f);
