        //13
        private async Task<String> GetDesgravamenDevolucion2PDF(FormatSettings formatSettings, ContractRequest request/*, String FingerprintImage, String BarCode*/)
        {
            String pdfbase64 = Convert.ToBase64String(System.IO.File.ReadAllBytes(Path.Combine(_hostingEnvironment.WebRootPath, formatSettings.PathFileBase)));

            System.Globalization.CultureInfo cultureinfo = new System.Globalization.CultureInfo("es-PE");
            DateTime fechaTransaccion = DateTime.MinValue;
            bool formatTransaccion = DateTime.TryParse(request.FechaTransaccion, cultureinfo, System.Globalization.DateTimeStyles.None, out fechaTransaccion);

            DateTime fechaNacimiento = DateTime.MinValue;
            bool formatNacimiento = DateTime.TryParse(request.FechaNacimientoCliente, cultureinfo, System.Globalization.DateTimeStyles.None, out fechaNacimiento);

            //Pagina 6

            var pag6 = Task.Run(() =>
            {
                if (formatTransaccion)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $" {fechaTransaccion.ToString("dd")}", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 442, 739, 7.0f);
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $" {fechaTransaccion.ToString("MM")}", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 483, 739, 7.0f);
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $" {fechaTransaccion.ToString("yy")}", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 527, 739, 7.0f);
                }
                pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $"{request.ApPaternoCliente}", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 44, 657, 15.5f);
                pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $"{request.ApMaternoCliente}", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 310, 657, 15.5f);
                pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $"{request.NombresCliente}", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 44, 631, 15.5f);
                pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, $"{request.NroDocumentoCliente}", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 392, 631, 15.5f);

                if (request.TipoMoneda == Moneda.Soles)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 130, 739, 0.0f);
                }
                else if (request.TipoMoneda == Moneda.Dolares)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 201, 739, 0.0f);
                }
                else
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 184, 730, 0.0f);
                }
                if (request.TipoCredito == Credito.Hipotecario)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 26, 716, 0.0f);
                }

                else if (request.TipoCredito == Credito.NuevoMiVivienda)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 114, 716, 0.0f);
                }
                else if (request.TipoCredito == Credito.PrestamoPersonalEstudios)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 215, 716, 0.0f);
                }
                else if (request.TipoCredito == Credito.Vehicular)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 321, 716, 0.0f);
                }
                else if (request.TipoCredito == Credito.Pymes)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 409, 716, 0.0f);
                }
                else if (request.TipoCredito == Credito.TechoPropio)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 485, 716, 0.0f);
                }
                else if (request.TipoCredito == Credito.PrestamoNegocio)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 26, 693, 0.0f);
                }
                else if (request.TipoCredito == Credito.PrestamoPersonal)
                {
                    pdfbase64 = PdfWorker.WriteTextInPdf(pdfbase64, "X", 6, 9, iTextSharp.text.Element.ALIGN_LEFT, 114, 693, 0.0f);
